&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;Humano&#239;de&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Nain.html&quot; title=&quot;Nain (sous-type)&quot;&gt;nain&lt;/a&gt;) de taille G, LM
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +0 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; 36 m (24 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +2
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 22, contact 10, pris au d&#233;pourvu 20 (armure +10, naturelle +1, parade +1, taille -1)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 90 (9d10+36)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +4, &lt;b&gt;Vig&lt;/b&gt; +10, &lt;b&gt;Vol&lt;/b&gt; +6 (+1 contre la terreur) ; +2 contre les sorts
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Capacit&#233;s d&#233;fensives&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#COURAGE&quot; title=&quot;Le guerrier&quot;&gt;courage&lt;/a&gt; +2 ; &lt;b&gt;Immunit&#233;&lt;/b&gt; fantasme, paralysie, poison
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Faiblesses&lt;/b&gt; sensible &#224; la lumi&#232;re
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 6 m (4 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; &lt;i&gt;hache d’armes de nain +2&lt;/i&gt;, +17/+12 (2d8+12/19-20/&#215;3)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Distance&lt;/b&gt; arbal&#232;te lourde de ma&#238;tre, +11 (2d8+1/19-20)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#ENTRAINEMENTAUXARMES&quot; title=&quot;Le guerrier&quot;&gt;entra&#238;nement aux armes&lt;/a&gt; (haches +2, arbal&#232;tes +1)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pouvoirs magiques&lt;/b&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; 9 ; &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; +6)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
1/jour — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Agrandissement.html&quot; title=&quot;Agrandissement&quot;&gt;agrandissement&lt;/a&gt;&lt;/i&gt; (sur soi uniquement), &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;&lt;/i&gt; (sur soi uniquement)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 19, &lt;b&gt;Dex&lt;/b&gt; 10, &lt;b&gt;Con&lt;/b&gt; 16, &lt;b&gt;Int&lt;/b&gt; 10, &lt;b&gt;Sag&lt;/b&gt; 15, &lt;b&gt;Cha&lt;/b&gt; 4
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +9, &lt;b&gt;BMO&lt;/b&gt; +13 (+15 pour le renversement et la destruction d’arme), &lt;b&gt;DMD&lt;/b&gt; 16 (20 contre la bousculade ou le croc-en-jambe)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt; (hache d’armes de nain), &lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection-Sup&#233;rieure.html&quot; title=&quot;Arme de pr&#233;dilection sup&#233;rieure&quot;&gt;Arme de pr&#233;dilection sup&#233;rieure&lt;/a&gt; (hache d’armes de nain), &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Puissance.html&quot; title=&quot;Attaque en puissance&quot;&gt;Attaque en puissance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Combat-Mont&#233;.html&quot; title=&quot;Combat mont&#233;&quot;&gt;Combat mont&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Destruction-Darme-Sup&#233;rieure.html&quot; title=&quot;Destruction d&amp;#39;arme sup&#233;rieure&quot;&gt;Destruction d’arme sup&#233;rieure&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Encha&#238;nement.html&quot; title=&quot;Encha&#238;nement&quot;&gt;Encha&#238;nement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Frappe-D&#233;cisive.html&quot; title=&quot;Frappe d&#233;cisive&quot;&gt;Frappe d&#233;cisive&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Renversement-Sup&#233;rieur.html&quot; title=&quot;Renversement sup&#233;rieur&quot;&gt;Renversement sup&#233;rieur&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sp&#233;cialisation-Martiale.html&quot; title=&quot;Sp&#233;cialisation martiale&quot;&gt;Sp&#233;cialisation martiale&lt;/a&gt; (hache d’armes de nain), &lt;a class=&quot;pagelink&quot; href=&quot;Succession-Dencha&#238;nements.html&quot; title=&quot;Succession d&amp;#39;encha&#238;nements&quot;&gt;Succession d’encha&#238;nements&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt; +3, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;quitation.html&quot; title=&quot;&#201;quitation&quot;&gt;&#201;quitation&lt;/a&gt; +8, &lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; +6, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +2, &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; +8
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; commun, commun des profondeurs, nain
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#ENTRAINEMENTAUXARMURES&quot; title=&quot;Le guerrier&quot;&gt;entra&#238;nement aux armures&lt;/a&gt; 2, &lt;a class=&quot;pagelink&quot; href=&quot;Duergar.html&quot; title=&quot;Duergar&quot;&gt;lentement mais s&#251;rement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Duergar.html&quot; title=&quot;Duergar&quot;&gt;stabilit&#233;&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;&#201;quipement de combat&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Potions-Magiques.html&quot; title=&quot;Les potions magiques&quot;&gt;potions&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Soins-Importants.html&quot; title=&quot;Soins importants&quot;&gt;soins importants&lt;/a&gt;&lt;/i&gt; (2), &lt;a class=&quot;pagelink&quot; href=&quot;Pierre-Tonnerre-(Objet).html&quot; title=&quot;Pierre tonnerre&quot;&gt; pierres-tonnerres&lt;/a&gt; (3) ; &lt;b&gt;&#201;quipement divers&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Harnois-(Armure).html&quot; title=&quot;Harnois&quot;&gt;harnois +1&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Hache-Darmes-Naine-(Arme).html&quot; title=&quot;Hache d&amp;#39;armes naine&quot;&gt;hache d’armes de nain +2&lt;/a&gt;&lt;/i&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arbal&#232;te-Lourde-(Arme).html&quot; title=&quot;Arbal&#232;te lourde&quot;&gt;arbal&#232;te lourde de ma&#238;tre&lt;/a&gt; avec &lt;a class=&quot;pagelink&quot; href=&quot;Carreaux-Darbal&#232;te-(Arme).html&quot; title=&quot;Carreaux d&amp;#39;arbal&#232;te (10)&quot;&gt;10 carreaux&lt;/a&gt;, 
&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Darmure-Naturelle.html&quot; title=&quot;Amulette d&amp;#39;armure naturelle&quot;&gt;amulette d’armure naturelle +1&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-R&#233;sistance.html&quot; title=&quot;Cape de r&#233;sistance&quot;&gt;cape de r&#233;sistance +1&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Anneau-De-Protection.html&quot; title=&quot;Anneau de protection&quot;&gt;anneau de protection +1&lt;/a&gt;&lt;/i&gt;, 129 po
&lt;/div&gt;
&lt;/div&gt;
&lt;/td&gt;&lt;td&gt;&lt;div&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 0 0; margin: 0 0 4px 8px&quot;&gt;
&lt;table CLASS=&quot;tablo autoalt&quot;&gt;&lt;caption&gt;Variantes de duergar&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Nom&lt;/td&gt;&lt;td&gt;FP&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Duergar.html&quot; title=&quot;Duergar&quot;&gt;Duergar&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1/3&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Esclavagiste-Duergar.html&quot; title=&quot;Esclavagiste duergar&quot;&gt;Esclavagiste duergar&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1/2&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tireur-D&#233;lite-Duergar.html&quot; title=&quot;Tireur d&amp;#39;&#233;lite duergar&quot;&gt;Tireur d&#39;&#233;lite duergar&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1/2&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bombardier-Duergar.html&quot; title=&quot;Bombardier duergar&quot;&gt;Bombardier duergar&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enclume-Duergar.html&quot; title=&quot;Enclume duergar&quot;&gt;Enclume duergar&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sergent-Duergar.html&quot; title=&quot;Sergent duergar&quot;&gt;Sergent duergar&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Scarab&#233;e-Crache-Noir.html&quot; title=&quot;Scarab&#233;e crache-noir&quot;&gt;Scarab&#233;e crache-noir&lt;/a&gt;&lt;/td&gt;&lt;td&gt;3&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lieutenant-Duergar.html&quot; title=&quot;Lieutenant duergar&quot;&gt;Lieutenant duergar&lt;/a&gt;&lt;/td&gt;&lt;td&gt;5&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Capitaine-Duergar.html&quot; title=&quot;Capitaine duergar&quot;&gt;Capitaine duergar&lt;/a&gt;&lt;/td&gt;&lt;td&gt;8&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-De-Corv&#233;e-Duergar.html&quot; title=&quot;Ma&#238;tre de corv&#233;e duergar&quot;&gt;Ma&#238;tre de corv&#233;e duergar&lt;/a&gt;&lt;/td&gt;&lt;td&gt;9&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marteau-Duergar.html&quot; title=&quot;Marteau duergar&quot;&gt;Marteau duergar&lt;/a&gt;&lt;/td&gt;&lt;td&gt;11&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grand-Pr&#234;tre-Duergar.html&quot; title=&quot;Grand pr&#234;tre duergar&quot;&gt;Grand pr&#234;tre duergar&lt;/a&gt;&lt;/td&gt;&lt;td&gt;12&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Scarab&#233;e-Juggernaut.html&quot; title=&quot;Scarab&#233;e juggernaut&quot;&gt;Scarab&#233;e juggernaut&lt;/a&gt;&lt;/td&gt;&lt;td&gt;14&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt; Chez les duergars, les soldats v&#233;t&#233;rans prennent la t&#234;te
d’un groupe de guerriers ou forment leur propre unit&#233;
d’&#233;lite. Ils utilisent toujours agrandissement avant d’engager
les hostilit&#233;s.
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
